/**
 * The template history the package ships (`data/template-history.json`,
 * generated by `bin/build-template-history.mjs` from the stable release
 * tags): per released version, the sha256 of every `templates/core/` file and
 * of every pack's `pack.json` and `files/`, keyed by the project path, plus
 * the full text of the files a three-way merge needs. Every hash is of the
 * raw template bytes, before token substitution.
 *
 * The file is data the CLI trusts only after {@link parseTemplateHistory}
 * has validated its whole shape; {@link loadTemplateHistory} never throws, so
 * a missing or damaged copy degrades a caller to "history unknown".
 */
import { readFileSync } from "node:fs";
import { templateHistoryPath } from "./assets.js";
import { isPrototypeSensitiveKey, isRecord } from "./merge-json.js";

/**
 * The only `schemaVersion` this CLI reads.
 *
 * @example
 * ```ts
 * if (history.schemaVersion !== TEMPLATE_HISTORY_SCHEMA_VERSION) throw new Error("unsupported");
 * ```
 */
export const TEMPLATE_HISTORY_SCHEMA_VERSION = 1;

/**
 * One release's templates: `core` maps each baseline project path to its
 * sha256; `packs` maps each pack name to its `pack.json` hash (`manifest`,
 * of the raw blob) and its files' hashes by project path.
 *
 * @example
 * ```ts
 * const entry: HistoryVersion = {
 *   core: { "package.json": "ab12..." },
 *   packs: { quality: { manifest: "cd34...", files: { "bin/check-file-budget.mjs": "ef56..." } } },
 * };
 * ```
 */
export interface HistoryVersion {
  readonly core: Readonly<Record<string, string>>;
  readonly packs: Readonly<
    Record<
      string,
      {
        readonly manifest: string;
        readonly files: Readonly<Record<string, string>>;
      }
    >
  >;
}

/**
 * The parsed template history: every stable release's templates, and the
 * full text of merge-relevant files keyed by the sha256 of that text.
 *
 * @example
 * ```ts
 * const history: TemplateHistory = { schemaVersion: 1, versions: {}, blobs: {} };
 * ```
 */
export interface TemplateHistory {
  readonly schemaVersion: typeof TEMPLATE_HISTORY_SCHEMA_VERSION;
  readonly versions: Readonly<Record<string, HistoryVersion>>;
  readonly blobs: Readonly<Record<string, string>>;
}

const SHA256_HEX = /^[0-9a-f]{64}$/;

/** An own property of `record`, or `undefined` -- never an inherited one. */
function own(record: Record<string, unknown>, key: string): unknown {
  return Object.hasOwn(record, key) ? record[key] : undefined;
}

/** `value` as a record, or a throw naming `where`. */
function asRecord(value: unknown, where: string): Record<string, unknown> {
  if (!isRecord(value)) throw new Error(`${where} must be a JSON object`);
  return value;
}

/** The record's entries, refusing a prototype-sensitive key. */
function safeEntries(
  record: Record<string, unknown>,
  where: string,
): [string, unknown][] {
  const entries = Object.entries(record);
  const bad = entries.find(([key]) => isPrototypeSensitiveKey(key));
  if (bad !== undefined) {
    throw new Error(`${where} has the forbidden key ${JSON.stringify(bad[0])}`);
  }
  return entries;
}

/** A `{ path: sha256 }` map, checked. */
function hashMap(value: unknown, where: string): Record<string, string> {
  return Object.fromEntries(
    safeEntries(asRecord(value, where), where).map(([path, hash]) => {
      if (typeof hash !== "string" || !SHA256_HEX.test(hash)) {
        throw new Error(`${where}[${JSON.stringify(path)}] is not a sha256`);
      }
      return [path, hash];
    }),
  );
}

function parseVersion(value: unknown, where: string): HistoryVersion {
  const entry = asRecord(value, where);
  const packsWhere = `${where}.packs`;
  const packs = safeEntries(
    asRecord(own(entry, "packs"), packsWhere),
    packsWhere,
  ).map(([name, raw]) => {
    const packWhere = `${packsWhere}[${JSON.stringify(name)}]`;
    const pack = asRecord(raw, packWhere);
    const manifest = own(pack, "manifest");
    if (typeof manifest !== "string" || !SHA256_HEX.test(manifest)) {
      throw new Error(`${packWhere}.manifest is not a sha256`);
    }
    return [
      name,
      { manifest, files: hashMap(own(pack, "files"), `${packWhere}.files`) },
    ] as const;
  });
  return {
    core: hashMap(own(entry, "core"), `${where}.core`),
    packs: Object.fromEntries(packs),
  };
}

/**
 * Parses and fully validates a template history's text: `schemaVersion`
 * {@link TEMPLATE_HISTORY_SCHEMA_VERSION}, a `versions` object of
 * `{ core, packs }` entries (every hash lowercase hex sha256, every pack with
 * a `manifest` hash and a `files` map), and a `blobs` object of strings keyed
 * by sha256. Key order is not checked (the generator's `--check` does that).
 *
 * @throws An `Error` naming the first defect: malformed JSON, a missing or
 * mistyped field, a non-hex hash, or a `__proto__`/`constructor`/`prototype`
 * key anywhere a name or path is a key.
 *
 * @example
 * ```ts
 * const history = parseTemplateHistory(readFileSync(templateHistoryPath(), "utf8"));
 * ```
 */
export function parseTemplateHistory(text: string): TemplateHistory {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (cause) {
    const detail = cause instanceof Error ? cause.message : String(cause);
    throw new Error(`template history is not valid JSON (${detail})`, {
      cause,
    });
  }
  const root = asRecord(parsed, "template history");
  const schemaVersion = own(root, "schemaVersion");
  if (schemaVersion !== TEMPLATE_HISTORY_SCHEMA_VERSION) {
    throw new Error(
      `template history has schemaVersion ${String(JSON.stringify(schemaVersion))}, expected ${String(TEMPLATE_HISTORY_SCHEMA_VERSION)}`,
    );
  }
  const versions = safeEntries(
    asRecord(own(root, "versions"), "versions"),
    "versions",
  ).map(
    ([version, entry]) =>
      [
        version,
        parseVersion(entry, `versions[${JSON.stringify(version)}]`),
      ] as const,
  );
  const blobs = safeEntries(asRecord(own(root, "blobs"), "blobs"), "blobs").map(
    ([hash, blob]) => {
      if (!SHA256_HEX.test(hash)) {
        throw new Error(`blobs key ${JSON.stringify(hash)} is not a sha256`);
      }
      if (typeof blob !== "string") {
        throw new Error(`blobs[${JSON.stringify(hash)}] is not a string`);
      }
      return [hash, blob] as const;
    },
  );
  return {
    schemaVersion: TEMPLATE_HISTORY_SCHEMA_VERSION,
    versions: Object.fromEntries(versions),
    blobs: Object.fromEntries(blobs),
  };
}

/**
 * Reads and parses the template history at `path` (default: the shipped
 * copy, {@link templateHistoryPath}). Never throws: a missing, unreadable or
 * invalid file -- or one that cannot be located at all -- is a `note` naming
 * the path and the reason, for a caller to report as "history unknown".
 *
 * @example
 * ```ts
 * const loaded = loadTemplateHistory();
 * if ("note" in loaded) undetermined.push(loaded.note);
 * ```
 */
export function loadTemplateHistory(
  path?: string,
): { history: TemplateHistory } | { note: string } {
  let resolved = path;
  try {
    resolved ??= templateHistoryPath();
    return { history: parseTemplateHistory(readFileSync(resolved, "utf8")) };
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    return {
      note: `the template history ${resolved ?? "data/template-history.json"} could not be read (${reason}) -- outdated packs cannot be detected`,
    };
  }
}

/**
 * A pack's `manifest` and `files` hashes as recorded at `version`, or
 * `undefined` when the history lacks that version or the version lacks that
 * pack. Only own keys are read: `"constructor"` is never a version or pack.
 *
 * @example
 * ```ts
 * const recorded = packHashesAt(history, "1.4.0", "quality");
 * if (recorded !== undefined) console.log(Object.keys(recorded.files));
 * ```
 */
export function packHashesAt(
  history: TemplateHistory,
  version: string,
  packName: string,
): HistoryVersion["packs"][string] | undefined {
  if (!Object.hasOwn(history.versions, version)) return undefined;
  const entry = history.versions[version];
  if (entry === undefined || !Object.hasOwn(entry.packs, packName)) {
    return undefined;
  }
  return entry.packs[packName];
}
